import XCTest
@testable import SRAppleApp

/// The live desk: `PanelReducer` against the web's own reducer.
///
/// `Fixtures/PanelOps/panel-ops.json` was GENERATED by the web code, not
/// written by hand: SR-Jkai-Core's `$lib/jkai/panel/apply.ts`, `schema.ts` and
/// `turn-desk.ts` reduced each case's ops — dropping the ones
/// `panelOpSchema.safeParse` refuses, as `ChatArea.deskTurnOp` does — and
/// SR-Main's `$lib/jkai/native-rich.ts` `nativePanel` filtered the result the
/// way a reload filters it for the phone. The fixture's `source` names the
/// commit of each (first cut: Core `ebefb18`, Main `3ea49d6ad`). Each case keeps:
///
/// - `raw`: the web page's sections and block ids, before the phone filter;
/// - `page`: what the drawer must show;
/// - `done` / `donePage`: the turn's `done.result.panel`, and what it shows.
///
/// If the desk schema or reducer changes, regenerate with
/// `scripts/panel-fixtures/generate.sh` rather than editing the JSON.
final class PanelReducerTests: XCTestCase {

    private struct Fixture: Decodable {
        let source: String
        let cases: [Case]
    }

    private struct Case: Decodable {
        let name: String
        let ops: [PanelOp]
        let raw: [RawSection]?
        let rawQuiet: Bool?
        let rawProducer: String?
        let page: PanelPage?
        let donePage: PanelPage?
    }

    private struct RawSection: Decodable, Equatable {
        let id: String
        let label: String
        let blocks: [String]
    }

    private func load() throws -> Data {
        if let url = Bundle(for: PanelReducerTests.self).url(forResource: "panel-ops", withExtension: "json") {
            return try Data(contentsOf: url)
        }
        let here = URL(fileURLWithPath: #filePath).deletingLastPathComponent()
        return try Data(contentsOf: here.appendingPathComponent("Fixtures/PanelOps/panel-ops.json"))
    }

    private func fixture() throws -> Fixture {
        try JSONDecoder().decode(Fixture.self, from: try load())
    }

    /// Each case's raw `done` object, which `PanelReducer.final` reads from a dictionary.
    private func doneResults() throws -> [String: [String: Any]] {
        let json = try JSONSerialization.jsonObject(with: try load()) as? [String: Any]
        var out: [String: [String: Any]] = [:]
        for item in (json?["cases"] as? [[String: Any]]) ?? [] {
            guard let name = item["name"] as? String, item.keys.contains("done") else { continue }
            out[name] = ["panel": item["done"] ?? NSNull()]
        }
        return out
    }

    // MARK: - Parity with the web

    func testTheFixturesNameWhereTheyCameFrom() throws {
        let fixture = try fixture()
        XCTAssertTrue(fixture.source.contains("SR-Jkai-Core"), fixture.source)
        XCTAssertTrue(fixture.source.contains("SR-Main"), fixture.source)
        XCTAssertGreaterThanOrEqual(fixture.cases.count, 10)
    }

    func testEveryCaseReducesToTheWebsPage() throws {
        for c in try fixture().cases {
            let reduced = PanelReducer.apply(nil, c.ops)
            let raw = reduced.map { $0.sections.map { RawSection(id: $0.id, label: $0.label, blocks: $0.blocks.map(\.id)) } }
            XCTAssertEqual(raw, c.raw, "\(c.name): the reduced page, before the phone filter")
            XCTAssertEqual(reduced?.quiet, c.rawQuiet, "\(c.name): quiet")
            XCTAssertEqual(reduced?.producer, c.rawProducer, "\(c.name): producer")
            XCTAssertEqual(PanelReducer.shown(reduced), c.page, "\(c.name): what the drawer shows")
        }
    }

    func testTheFinishedPageIsWhatAReloadWouldShow() throws {
        let cases = try fixture().cases
        let results = try doneResults()
        XCTAssertFalse(results.isEmpty)
        for (name, result) in results {
            let expected = cases.first { $0.name == name }?.donePage
            switch PanelReducer.final(fromResult: result) {
            case .keep:
                XCTFail("\(name): a done result with a panel key must not keep the live page")
            case .none:
                XCTAssertNil(expected, "\(name)")
            case .page(let page):
                XCTAssertEqual(PanelReducer.shown(page), expected, "\(name)")
            }
        }
    }

    /// The real producer's stream lands on the same page as its own `done`.
    func testTheStreamedOpsAndTheDonePageAgree() throws {
        for c in try fixture().cases where c.name.hasPrefix("turn-desk") {
            XCTAssertEqual(PanelReducer.shown(PanelReducer.apply(nil, c.ops)), c.donePage, c.name)
        }
    }

    // MARK: - Replays and reconnects

    /// A reconnect can hand the same ops over twice. Upserts are by id and a
    /// head is a head, so the page must not change.
    func testReplayingEveryOpTwiceChangesNothing() throws {
        for c in try fixture().cases {
            let once = PanelReducer.apply(nil, c.ops)
            let twice = PanelReducer.apply(once, c.ops)
            // `reset` clears everything before it, so a replay rebuilds from it.
            XCTAssertEqual(PanelReducer.shown(twice), PanelReducer.shown(once), c.name)
        }
    }

    // MARK: - Receiver-tolerant

    func testAnOpThisBuildCannotReadIsANoOp() throws {
        let ops = try JSONDecoder().decode([PanelOp].self, from: Data("""
        [{"kind": "upsert", "section": "s", "block": {"id": "a", "type": "kv", "items": [{"label": "x", "value": "y"}]}},
         {"kind": "warp", "speed": 9},
         {"kind": "head"},
         {"kind": "head", "head": "not an object"},
         {"kind": "remove", "id": 7},
         {"kind": "upsert", "section": "", "block": {"id": "b", "type": "kv", "items": [{"label": "x", "value": "y"}]}},
         42, "panel", null, [], {}]
        """.utf8))
        XCTAssertEqual(ops.filter { $0 != .ignored }.count, 1)
        let page = PanelReducer.apply(nil, ops)
        XCTAssertEqual(page?.sections.map(\.id), ["s"])
        XCTAssertEqual(page?.head, PanelReducer.defaultHead)
    }

    /// A block type from a newer server is kept on the reduced page — it holds
    /// its place and its id, as it would on a web client that knows it — and
    /// is simply not drawn.
    func testAnUnknownBlockTypeHoldsItsPlaceButIsNotDrawn() throws {
        let ops = try JSONDecoder().decode([PanelOp].self, from: Data("""
        [{"kind": "upsert", "section": "s", "block": {"id": "a", "type": "kv", "items": [{"label": "x", "value": "y"}]}},
         {"kind": "upsert", "section": "s", "block": {"id": "h", "type": "hologram", "beam": true}},
         {"kind": "upsert", "section": "t", "block": {"id": "only", "type": "hologram"}}]
        """.utf8))
        let page = PanelReducer.apply(nil, ops)
        XCTAssertEqual(page?.sections.map { $0.blocks.map(\.id) }, [["a", "h"], ["only"]])
        let shown = PanelReducer.shown(page)
        XCTAssertEqual(shown?.sections.map(\.id), ["s"], "a section with nothing drawable is not shown")
        XCTAssertEqual(shown?.sections.first?.blocks.map(\.id), ["a"])
    }

    func testAPanelFrameWithNoUsableOpIsIgnored() throws {
        for json in [#"{"type": "panel"}"#, #"{"type": "panel", "op": 3}"#, #"{"type": "panel", "op": {"kind": "nope"}}"#] {
            let frame = try JSONDecoder().decode(PanelFrame.self, from: Data(json.utf8))
            XCTAssertEqual(frame.op, .ignored, json)
        }
        let frame = try JSONDecoder().decode(PanelFrame.self, from: Data(#"{"type":"panel","op":{"kind":"quiet"}}"#.utf8))
        XCTAssertEqual(frame.op, .quiet)
    }

    func testDoneWithoutAPanelKeepsTheLivePageAndNullClearsIt() {
        XCTAssertEqual(PanelReducer.final(fromResult: ["message": "hi"]), .keep)
        XCTAssertEqual(PanelReducer.final(fromResult: ["panel": NSNull()]), .none)
        XCTAssertEqual(PanelReducer.final(fromResult: ["panel": "junk"]), .keep, "a panel that is not a page is the web's `undefined`: keep")
    }

    /// The live page is what the drawer pages to while the turn runs.
    func testALivePageIsOnTheDesk() throws {
        let ops = try JSONDecoder().decode([PanelOp].self, from: Data("""
        [{"kind": "head", "head": {"kicker": "This turn", "context": ["mail"], "title": "Mail"}},
         {"kind": "upsert", "section": "mail", "sectionLabel": "Mail", "block": {"id": "m", "type": "rows", "rows": [{"id": "1", "title": "Hi"}]}}]
        """.utf8))
        let live = PanelReducer.shown(PanelReducer.apply(nil, ops))
        let turns = [
            DeskTurn(id: "u", isAssistant: false, page: nil),
            DeskTurn(id: "live", isAssistant: true, page: live),
        ]
        XCTAssertEqual(DeskPager.choose(turns: turns, focus: nil), DeskPager.Choice(index: 0, held: false))
        XCTAssertEqual(live?.head.context, ["mail"])
    }

    // MARK: - The schema's caps

    private func prose(_ id: String) -> PanelBlock {
        PanelBlock(id: id, content: .prose("x", tone: nil))
    }

    /// Core's schema refuses a section of more than 24 blocks, so the 25th NEW
    /// block into one is dropped; a block already there is still replaced.
    func testANewBlockIntoAFullSectionIsDropped() {
        let ops = (0..<24).map { PanelOp.upsert(section: "s", sectionLabel: nil, block: prose("b\($0)")) }
        let full = PanelReducer.apply(nil, ops)
        XCTAssertEqual(full?.sections.first?.blocks.count, PanelReducer.maxBlocksPerSection)

        let over = PanelReducer.apply(full, .upsert(section: "s", sectionLabel: nil, block: prose("b24")))
        XCTAssertEqual(over, full, "the 25th block goes nowhere")

        let replaced = PanelReducer.apply(full, .upsert(section: "s", sectionLabel: nil, block: PanelBlock(id: "b3", content: .prose("new", tone: nil))))
        XCTAssertEqual(replaced?.sections.first?.blocks.count, 24)
        XCTAssertEqual(replaced?.sections.first?.blocks[3].content, .prose("new", tone: nil), "replace in place still works")

        // A block moving in from another section is new to this one.
        let other = PanelReducer.apply(full, .upsert(section: "t", sectionLabel: nil, block: prose("t0")))
        let moved = PanelReducer.apply(other, .upsert(section: "s", sectionLabel: nil, block: prose("t0")))
        XCTAssertEqual(moved, other)

        // Another section still takes blocks.
        XCTAssertEqual(other?.sections.map(\.id), ["s", "t"])
    }

    /// And a page of more than 12 sections: the 13th NEW section is dropped,
    /// while a block into one of the twelve still lands.
    func testANewSectionOnAFullPageIsDropped() {
        let ops = (0..<12).map { PanelOp.upsert(section: "s\($0)", sectionLabel: nil, block: prose("b\($0)")) }
        let full = PanelReducer.apply(nil, ops)
        XCTAssertEqual(full?.sections.count, PanelReducer.maxSectionsPerPage)

        let over = PanelReducer.apply(full, .upsert(section: "s12", sectionLabel: "Late", block: prose("late")))
        XCTAssertEqual(over, full)

        let into = PanelReducer.apply(full, .upsert(section: "s4", sectionLabel: nil, block: prose("more")))
        XCTAssertEqual(into?.sections.count, 12)
        XCTAssertEqual(into?.sections[4].blocks.map(\.id), ["b4", "more"])

        let replaced = PanelReducer.apply(full, .upsert(section: "s0", sectionLabel: nil, block: PanelBlock(id: "b0", content: .prose("again", tone: nil))))
        XCTAssertEqual(replaced?.sections[0].blocks.first?.content, .prose("again", tone: nil))
    }

    /// The page cap still holds over both: 40 blocks across sections of fewer than 24.
    func testThePageCapStillHolds() {
        let ops = (0..<41).map { PanelOp.upsert(section: "s\($0 / 20)", sectionLabel: nil, block: prose("b\($0)")) }
        let page = PanelReducer.apply(nil, ops)
        XCTAssertEqual(page?.sections.reduce(0) { $0 + $1.blocks.count }, PanelReducer.maxBlocksPerPage)
    }
}
